INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Ergebnisse ohne Ziele bewerten?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele sind Referenz"}, {"text": "Ja", "correct": false, "because": "Fehlende Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Ergebnisbewertung?', 3, '[{"text": "Erfolg messen", "correct": true, "because": "Überprüft Zielerreichung"}, {"text": "Code optimieren", "correct": false, "because": "Anderer Fokus"}, {"text": "Design verbessern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren gehören zur Ergebnisbewertung?', 5, '[{"text": "Zielerreichung", "correct": true, "because": "Misst Erfolg"}, {"text": "Kundenzufriedenheit", "correct": true, "because": "Zeigt Akzeptanz"}, {"text": "Hardware-Leistung", "correct": false, "because": "Kontextabhängig"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kundenzufriedenheit ist messbar. b) Ziele sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) essenziell für Bewertung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ergebnisbewertung?', 4, '[{"text": "Anforderungen", "correct": false, "because": "Grundlage der Bewertung"}, {"text": "Feedback", "correct": false, "because": "Zeigt Zufriedenheit"}, {"text": "Schriftgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kundenzufriedenheit subjektiv ist?', 2, '[{"text": "Ja", "correct": true, "because": "Abhängig von Wahrnehmung"}, {"text": "Nein", "correct": false, "because": "Nicht rein objektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich zur Ergebnisbewertung?', 3, '[{"text": "Umfragen", "correct": true, "because": "Misst Zufriedenheit"}, {"text": "Code-Analyse", "correct": false, "because": "Technischer Fokus"}, {"text": "Random Guess", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen eine Bewertung effektiv?', 5, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Vergleichsbasis"}, {"text": "Kundenfeedback", "correct": true, "because": "Nutzerperspektive"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht relevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ergebnisse sind nur Zahlen. b) Zufriedenheit ist unwichtig. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Qualitativ und wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Ergebnisbewertung?', 4, '[{"text": "Ziele", "correct": false, "because": "Definiert Erfolg"}, {"text": "Metriken", "correct": false, "because": "Misst Fortschritt"}, {"text": "Monitorauflösung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Bewertung nur für Kunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Team und Prozess"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sind für die Bewertung entscheidend?', 4, '[{"text": "Kundenbewertungen", "correct": true, "because": "Zeigt Zufriedenheit"}, {"text": "Zielvorgaben", "correct": true, "because": "Vergleichsgrundlage"}, {"text": "Code-Zeilen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ergebnisse nur einmal bewertet werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Laufende Überprüfung nötig"}, {"text": "Ja", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Ergebnisbewertung?', 3, '[{"text": "Objektivität", "correct": true, "because": "Sichert Fairness"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Subjektive Meinungen", "correct": false, "because": "Weniger verlässlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ziele müssen SMART sein. b) Kundenzufriedenheit ist nebensächlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Ergebnisbewertung?', 5, '[{"text": "Verbesserungspotenzial", "correct": true, "because": "Zeigt Schwächen"}, {"text": "Kundentreue", "correct": true, "because": "Zufriedenheit stärken"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bewertung unwichtig?', 3, '[{"text": "Kundenmeinungen", "correct": false, "because": "Zeigt Akzeptanz"}, {"text": "Zielvorgaben", "correct": false, "because": "Misst Erfolg"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt die Bewertung das Feedback?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Feedback bleibt zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Bewertung nur quantitativ ist?', 2, '[{"text": "Nein", "correct": true, "because": "Qualitativ ebenso wichtig"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist für die Ergebnisbewertung entscheidend?', 4, '[{"text": "KPIs", "correct": true, "because": "Misst Erfolg objektiv"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Unzuverlässig"}]');
